<script lang="ts">import {goto} from '$app/navigation'; let email=$state(''); let password=$state(''); let error=$state(''); function submit(){if(!email||!password){error='Enter your email and password.';return} goto('/dashboard')}</script><svelte:head><title>Login · RegenFeed</title></svelte:head><main class="auth wrap"><p class="eyebrow">WELCOME BACK</p><h1>Log in to<br/><em>your loop.</em></h1>{#if error}<p class="error">{error}</p>{/if}<form onsubmit={(e)=>{e.preventDefault();submit()}}><label>Email<input bind:value={email} type="email" required /></label><label>Password<input bind:value={password} type="password" required /></label><button class="btn primary">Log in ↗</button></form><p class="muted">New to RegenFeed? <a href="/auth/register">Create an account</a></p></main>
